import { IEnvironmentAware } from "../environment-aware";
import * as constructs from "constructs";
/**
 * Indicates that this resource can be referenced as a Adapter.
 *
 * @stability experimental
 */
export interface IAdapterRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a Adapter resource.
     */
    readonly adapterRef: AdapterReference;
}
/**
 * A reference to a Adapter resource.
 *
 * @struct
 * @stability external
 */
export interface AdapterReference {
    /**
     * The Arn of the Adapter resource.
     */
    readonly adapterArn: string;
}
